pub const SCHEMA_TRUST_ANCHOR_SCHEMA_ID: &str = "dc24b657d17c28a043bb29306582f2730a939b5eb81d5e3fda8d8bd1108b6630";
pub const OWNERSHIP_MANIFEST_SCHEMA_ID: &str = "440fd1b7b03314e42d89e003a6ed1c5070a1fc8c7a2ce285f59c56b4b07bda77";
pub const OWNERSHIP_TRANSFER_SCHEMA_ID: &str = "92633e63eec51c7afed83f5c7477d137b27d26c1922eb0eed35ed2ef22c3f541";
pub const EMPTY_SCHEMA_PREIMAGE_HEX: &str = "6461772d736368656d612d7631007b7d";
